198: delete_oldest_chats <- function(path = getwd(), persist = NULL) {
199:   if (is.null(persist)) {
200:     persist <- should_persist()
201:   }
202: 
203:   files <- get_chat_files(path, persist = persist)
204:   if (length(files) > 3) {
205:     to_delete <- files[4:length(files)]
206:     unlink(to_delete)
207:   }
208: 
209:   if (!persist) {
210:     return(invisible(NULL))
211:   }
212: 
213:   base_dir <- get_config_dir("chats")
214:   if (!dir.exists(base_dir)) {
215:     return(invisible(NULL))
216:   }
217: 
218:   all_dirs <- list.dirs(base_dir, recursive = FALSE, full.names = TRUE)
219:   all_files <- unlist(lapply(all_dirs, function(d) {
220:     list.files(d, pattern = "\\.rds$", full.names = TRUE)
221:   }))
222: 
223:   if (length(all_files) > 15) {
224:     info <- file.info(all_files)
225:     all_files_sorted <- all_files[order(info$mtime, decreasing = TRUE)]
226:     to_delete <- all_files_sorted[16:length(all_files_sorted)]
227:     unlink(to_delete)
228:   }
229: 
230:   invisible(NULL)
231: }
