360: check_inherits <- function(
361:   x,
362:   class,
363:   x_arg = caller_arg(x),
364:   call = caller_env()
365: ) {
366:   if (!inherits(x, class)) {
367:     cli::cli_abort(
368:       "{.arg {x_arg}} must be a {.cls {class}}, not {.obj_type_friendly {x}}.",
369:       call = call
370:     )
371:   }
372: 
373:   invisible(NULL)
374: }
