remove_yaml_frontmatter <- function(text_content) {
  content_start <- 1
  if (length(text_content) > 0 && text_content[1] == "---") {
    yaml_end <- which(text_content == "---")
    if (length(yaml_end) >= 2) {
      content_start <- yaml_end[2] + 1
    }
  }
  text_content[content_start:length(text_content)]
}

